import{_ as t,o as a,c as s,a4 as r}from"./chunks/framework.ClGzHnIj.js";const m=JSON.parse('{"title":"En direct","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://lognebudo.github.io/llmxray/docs/fr/guide/live.html"}]]},"headers":[],"relativePath":"fr/guide/live.md","filePath":"fr/guide/live.md","lastUpdated":1792432116000}'),o={name:"fr/guide/live.md"};function n(l,e,i,u,d,c){return a(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="en-direct" tabindex="-1">En direct <a class="header-anchor" href="#en-direct" aria-label="Permalink to &quot;En direct&quot;">​</a></h1><p>La page <strong>En direct</strong> montre ce que vos <em>autres</em> outils envoient réellement à Ollama : VS Code Copilot, Open WebUI, Continue, n8n, un script Python. Tour par tour, avec ce que le cache a gardé et ce qu&#39;il a jeté.</p><p><strong>Élément de la barre latérale :</strong> En direct (au-dessus du Labo de cache) <strong>Route :</strong> <code>/live</code><strong>Ajouté dans :</strong> v0.7.2 (octobre 2026) <strong>Nécessite :</strong> rien de plus. Le port d&#39;observation s&#39;ouvre avec LLMxRay. Les chiffres de cache demandent Ollama 0.33.3 ou plus récent, qui est la version qui les rapporte.</p><h2 id="a-quoi-ca-sert" tabindex="-1">À quoi ça sert ? <a class="header-anchor" href="#a-quoi-ca-sert" aria-label="Permalink to &quot;À quoi ça sert ?&quot;">​</a></h2><p>Toutes les autres pages de LLMxRay observent un trafic que LLMxRay génère lui-même. Celle-ci observe un trafic que vous ne contrôlez pas : la boucle d&#39;agent que Copilot fait tourner sur votre GPU, l&#39;interface de chat de votre équipe, le workflow qui appelle un modèle quarante fois par heure.</p><p>C&#39;est là que les installations locales ralentissent sans bruit. Un assistant de code envoie plusieurs milliers de tokens d&#39;instructions et de définitions d&#39;outils avant que vous ayez tapé un mot, place l&#39;état de l&#39;éditeur près du haut de l&#39;invite, et renvoie toute la conversation plus chaque résultat d&#39;outil à chaque tour. Rien de cela n&#39;est visible depuis l&#39;outil ; tout l&#39;est dans les chiffres du démon dès que quelque chose se place entre les deux.</p><p>C&#39;est ce qu&#39;est le port d&#39;observation : un sosie d&#39;Ollama qui transmet tout au vrai démon et garde les chiffres.</p><h2 id="mise-en-place" tabindex="-1">Mise en place <a class="header-anchor" href="#mise-en-place" aria-label="Permalink to &quot;Mise en place&quot;">​</a></h2><p>L&#39;état vide de la page <em>est</em> la mise en place. Elle affiche une adresse, par défaut :</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://localhost:11435</span></span></code></pre></div><p>Utilisez-la partout où un outil demande l&#39;adresse d&#39;Ollama. La page indique le champ exact pour chaque outil courant :</p><table tabindex="0"><thead><tr><th>Outil</th><th>Où va l&#39;adresse</th></tr></thead><tbody><tr><td><strong>VS Code Copilot</strong></td><td>Installez l&#39;extension Ollama (éditeur Ollama) depuis le Marketplace ; l&#39;ancien fournisseur Ollama intégré à VS Code est déprécié. Puis Paramètres, <code>ollama.endpoint</code>, ou <em>Chat: Manage Language Models</em>, Ollama, URL. Lancez <em>Ollama: Refresh Models</em> et choisissez un modèle dans la section Ollama du sélecteur.</td></tr><tr><td><strong>Open WebUI</strong></td><td>Panneau d&#39;administration, Paramètres, Connexions, URL de l&#39;API Ollama. Depuis un conteneur Docker, <code>http://host.docker.internal:11435</code>.</td></tr><tr><td><strong>Continue</strong></td><td><code>apiBase</code> sur chaque modèle Ollama dans <code>config.yaml</code>.</td></tr><tr><td><strong>n8n</strong></td><td>URL de base de l&#39;identifiant Ollama.</td></tr><tr><td><strong>Python / curl</strong></td><td><code>ollama.Client(host=&#39;http://localhost:11435&#39;)</code>, <code>base_url=&#39;http://localhost:11435/v1&#39;</code> pour le SDK OpenAI, ou <code>export OLLAMA_HOST=localhost:11435</code> pour la ligne de commande (<code>$env:OLLAMA_HOST = &quot;localhost:11435&quot;</code> sous PowerShell).</td></tr></tbody></table><p>Envoyez un message depuis l&#39;outil. La page passe d&#39;elle-même en vue directe. Pas de bouton Enregistrer, pas de redémarrage.</p><p>Le port se comporte exactement comme Ollama, bannière racine comprise : les outils qui sondent <code>/</code> ou <code>/api/tags</code> avant de faire confiance à un serveur voient un démon. Téléchargements, listes et suppressions de modèles passent sans être enregistrés ; seuls les tours de modèle sont gardés (<code>/api/chat</code>, <code>/api/generate</code>, <code>/api/embed</code>, et les équivalents OpenAI <code>/v1/chat/completions</code>, <code>/v1/completions</code>, <code>/v1/embeddings</code>).</p><h3 id="changer-ou-desactiver-le-port" tabindex="-1">Changer ou désactiver le port <a class="header-anchor" href="#changer-ou-desactiver-le-port" aria-label="Permalink to &quot;Changer ou désactiver le port&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> llmxray</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --observe-port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 11500</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # un autre port</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> llmxray</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-observe</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # ne pas l&#39;ouvrir</span></span></code></pre></div><p>Sous Docker, exposez le port (<code>-p 11435:11435</code>) et utilisez <code>OBSERVE_PORT</code> ou <code>OBSERVE=0</code>. Si le port par défaut est déjà pris, la page le dit et le reste de LLMxRay fonctionne comme avant.</p><h2 id="la-vue-directe" tabindex="-1">La vue directe <a class="header-anchor" href="#la-vue-directe" aria-label="Permalink to &quot;La vue directe&quot;">​</a></h2><h3 id="constats" tabindex="-1">Constats <a class="header-anchor" href="#constats" aria-label="Permalink to &quot;Constats&quot;">​</a></h3><p>Des phrases simples en haut de page, chacune avec un lien vers le tour qui la prouve. Elles n&#39;apparaissent qu&#39;avec assez de preuves ; un tour bruyant n&#39;en déclenche jamais une.</p><ul><li><strong>« <em>Client</em> envoie des invites de N tokens, mais <em>modèle</em> est chargé avec un contexte de M tokens. »</strong> Le démon a rejeté la requête d&#39;emblée, avec les deux nombres dans sa réponse : un seul tour suffit comme preuve. Le remède est la longueur de contexte dans les réglages d&#39;Ollama ; les assistants de code demandent 32K à 64K, et ce contexte plus grand doit tenir en mémoire vidéo à côté des poids.</li><li><strong>« <em>Client</em> a perdu le cache à ce tour avec <em>modèle</em> : X % conservés au tour précédent, Y % à celui-ci. »</strong> Un seul tour, pas une médiane : le client était en cache et, à ce tour, sa part de cache a chuté de quarante points ou plus. La phrase dit d&#39;abord si le modèle est resté chargé, d&#39;après le temps de chargement rapporté par le démon : quelques millisecondes signifient que le cache KV était encore là et que rien n&#39;en a été réutilisé, donc un préfixe qui ne correspondait plus, pas une éviction. Un tour où le modèle a été rechargé n&#39;est jamais compté comme une chute. Elle donne ensuite la taille de l&#39;invite et le token où elle a cessé de correspondre au tour précédent. Seule la dernière chute par client et modèle est affichée.</li><li><strong>« <em>Client</em> relit environ N tokens à chaque tour avec <em>modèle</em>. »</strong> La part médiane de cache sur au moins trois tours est inférieure à la moitié, et la partie recalculée fait au moins 500 tokens. La phrase nomme le token où l&#39;invite cesse de correspondre au tour précédent, quand le démon a rapporté un compte pour l&#39;y ramener.</li><li><strong>« <em>Modèle</em> tourne à N % sur le processeur. »</strong> D&#39;après le rapport de chargement du démon lui-même (<code>/api/ps</code>) : la taille chargée contre la partie en mémoire vidéo. La cause habituelle est un contexte qui ne tient plus à côté des poids ; le remède habituel, un contexte plus petit ou un cache KV quantifié.</li><li><strong>« Les schémas d&#39;outils représentent N % de chaque invite de <em>client</em>. »</strong> Les définitions d&#39;outils occupent plus du quart de l&#39;invite, avec le nombre de celles réellement utilisées dans les tours vus. Elles sont dans le préfixe stable, donc en cache, mais elles occupent le contexte.</li></ul><h3 id="flux-des-tours" tabindex="-1">Flux des tours <a class="header-anchor" href="#flux-des-tours" aria-label="Permalink to &quot;Flux des tours&quot;">​</a></h3><p>Du plus récent au plus ancien : heure, client et mode (agent quand des outils étaient proposés, chat sinon), modèle, tokens d&#39;invite, part servie depuis le cache sous forme de barre colorée, temps de préremplissage, vitesse de génération, appels d&#39;outils. La part de cache est la seule colonne colorée : un client au préfixe rompu se voit de l&#39;autre bout de la pièce.</p><p>Les clients sont nommés d&#39;après leur User-Agent et la forme de la requête. Un client inconnu garde son nom de produit ; l&#39;en-tête brut est au survol.</p><h3 id="un-tour-en-detail" tabindex="-1">Un tour en détail <a class="header-anchor" href="#un-tour-en-detail" aria-label="Permalink to &quot;Un tour en détail&quot;">​</a></h3><p>Cliquez sur une ligne.</p><p><strong>De quoi est faite l&#39;invite.</strong> Une barre découpée en instructions système, schémas d&#39;outils, historique et résultats d&#39;outils, et votre message, ramenée au compte de tokens du démon. Le découpage est en caractères : c&#39;est une proportion, pas un tokeniseur.</p><p><strong>Où le cache a rompu.</strong> La page garde l&#39;invite précédente du même client et du même modèle et trouve le premier caractère où celle-ci diffère. Le cache KV ne survit que sur un préfixe partagé : ce point est exactement là où la réutilisation s&#39;est arrêtée et le recalcul a commencé. La page dit combien de tokens ont suivi, et ce qu&#39;aurait été le préremplissage si la partie changeante était venue en dernier, extrapolé linéairement depuis le temps de préremplissage de ce tour.</p><p>Avec <strong>Conserver le texte des invites</strong> activé, le texte des deux côtés de la rupture s&#39;affiche, la partie verte en cache, la rouge non. C&#39;est ce qui vous dit <em>quelle</em> valeur a bougé : une position de curseur, un horodatage, un fragment réordonné.</p><p><strong>Les chiffres.</strong> Tokens d&#39;invite, tokens en cache, préremplissage avec le débit réel (tokens non mis en cache sur le temps de préremplissage, jamais le total), génération, appels d&#39;outils, le contexte avec lequel le modèle a été chargé et la part qui tourne sur le processeur, le moteur, le protocole, le User-Agent.</p><h3 id="par-client" tabindex="-1">Par client <a class="header-anchor" href="#par-client" aria-label="Permalink to &quot;Par client&quot;">​</a></h3><p>Une carte par client : tours, tokens, appels d&#39;outils, préremplissage total, et <strong>Gain si cache corrigé</strong> : le préremplissage que ces tours auraient évité si leurs invites étaient restées en cache jusqu&#39;au nouveau message. C&#39;est extrapolé des chiffres de la session. Le <a href="./cache-lab.html">Labo de cache</a> <em>mesure</em> la même chose en renvoyant une invite ; cette page ne fait qu&#39;observer, d&#39;où le « environ ».</p><h2 id="confidentialite" tabindex="-1">Confidentialité <a class="header-anchor" href="#confidentialite" aria-label="Permalink to &quot;Confidentialité&quot;">​</a></h2><p>Désactivé par défaut : seuls les comptes et les durées sont gardés. L&#39;enregistrement de chaque tour (tokens, cache, durées, client, modèle, jamais le texte) va dans un fichier sous votre dossier personnel, <code>~/.llmxray/observe/turns-&lt;date&gt;.jsonl</code>, un par jour. Au redémarrage, LLMxRay remet les 500 derniers tours en place : En direct, les <a href="./runs.html">Exécutions</a> et les outils MCP reprennent là où ils s&#39;étaient arrêtés. Les fichiers de plus de 30 jours sont supprimés. <strong>Effacer</strong> oublie tout, fichiers compris, après avoir demandé. Définissez <code>LLMXRAY_DATA_DIR</code> pour les garder ailleurs.</p><p><strong>Conserver le texte des invites</strong> enregistre en plus les corps de requête à côté (<code>~/.llmxray/observe/&lt;date&gt;.jsonl</code>, un fichier par jour, avec les mêmes 30 jours) et affiche le texte autour de chaque rupture sur la page. Cela débloque aussi la <strong>vue de la requête</strong> sous le tour : la requête rendue comme une conversation, un bloc par message avec de vrais retours à la ligne, les appels d&#39;outils en cartes, les résultats d&#39;outils repliés, et la liste des outils avec nom, description, nombre de paramètres et taille. La rupture du cache est dessinée dans le message où elle est tombée. Une recherche couvre messages et outils, et un onglet JSON brut avec Copier et Télécharger garde chaque octet accessible. Désactivez-le et le texte conservé est retiré de la mémoire ; les fichiers restent jusqu&#39;à leurs 30 jours ou jusqu&#39;à ce que vous appuyiez sur Effacer.</p><p>Dans les deux modes, rien ne quitte votre machine. Le port d&#39;observation parle à l&#39;adresse Ollama avec laquelle LLMxRay a été lancé, et à rien d&#39;autre.</p><h2 id="envoyer-les-tours-vers-votre-visualiseur-de-traces" tabindex="-1">Envoyer les tours vers votre visualiseur de traces <a class="header-anchor" href="#envoyer-les-tours-vers-votre-visualiseur-de-traces" aria-label="Permalink to &quot;Envoyer les tours vers votre visualiseur de traces&quot;">​</a></h2><p>Si votre équipe lit déjà ses traces dans Jaeger, Arize Phoenix, Langfuse ou Grafana, LLMxRay peut y envoyer ses tours. Chaque appel au modèle devient un span OpenTelemetry et chaque exécution une trace : le visualiseur montre la même cascade que les <a href="./runs.html">Exécutions</a>, avec entre deux appels un span pour les outils demandés par le modèle.</p><p>Sous l&#39;interrupteur de confidentialité, dans <strong>Envoyer les tours vers votre visualiseur de traces</strong>, donnez l&#39;adresse du collecteur et appuyez sur <strong>Commencer l&#39;envoi</strong>. <strong>Envoyer un span de test</strong> vérifie d&#39;abord l&#39;adresse. LLMxRay envoie de l&#39;OTLP sur HTTP (protobuf, l&#39;encodage par défaut d&#39;OTLP) à l&#39;adresse suivie de <code>/v1/traces</code> ; les réglages standard <code>OTEL_EXPORTER_OTLP_ENDPOINT</code> et <code>OTEL_EXPORTER_OTLP_HEADERS</code> la remplissent aussi, pour Docker ou un script.</p><table tabindex="0"><thead><tr><th>Visualiseur</th><th>Le lancer</th><th>Adresse</th></tr></thead><tbody><tr><td>Jaeger</td><td><code>docker run -p 16686:16686 -p 4318:4318 jaegertracing/jaeger</code></td><td><code>http://localhost:4318</code>, puis ouvrez localhost:16686</td></tr><tr><td>Arize Phoenix</td><td><code>docker run -p 6006:6006 arizephoenix/phoenix</code></td><td><code>http://localhost:6006</code></td></tr><tr><td>Langfuse</td><td></td><td><code>https://cloud.langfuse.com/api/public/otel</code>, avec un en-tête <code>Authorization: Basic</code> fait de vos clés publique et secrète</td></tr><tr><td>Grafana Tempo, un OpenTelemetry Collector</td><td></td><td>son adresse OTLP HTTP, en général le port 4318</td></tr></tbody></table><p>Chaque span porte les attributs GenAI que les visualiseurs lisent déjà (<code>gen_ai.request.model</code>, <code>gen_ai.usage.input_tokens</code>, <code>gen_ai.usage.output_tokens</code>, <code>gen_ai.response.finish_reasons</code>) et ce que seul LLMxRay sait, sous <code>llmxray.*</code> : le client, les tokens en cache et leur part, les temps de préremplissage, de chargement et d&#39;attente, si le démon a coupé l&#39;invite, la part du modèle en RAM système, les outils appelés.</p><p>Le texte des invites ne part que si <strong>Conserver le texte des invites</strong> est activé <em>et</em> <strong>Inclure le texte des invites dans chaque span</strong> aussi, sous <code>gen_ai.input.messages</code> et <code>gen_ai.output.messages</code>. Langfuse Cloud est hors de votre machine ; le panneau le dit. Les en-têtes, souvent une clé, sont gardés tels quels dans <code>~/.llmxray/export.json</code>. Si le collecteur est injoignable, le panneau dit pourquoi, le tour suivant réessaie, et LLMxRay continue de fonctionner.</p><h2 id="ce-que-cette-page-ne-fait-pas" tabindex="-1">Ce que cette page ne fait pas <a class="header-anchor" href="#ce-que-cette-page-ne-fait-pas" aria-label="Permalink to &quot;Ce que cette page ne fait pas&quot;">​</a></h2><p>Elle ne tokenise pas (les proportions sont en caractères, les comptes sont ceux du démon), et elle ne modifie rien de ce qui la traverse. C&#39;est une fenêtre, pas un filtre.</p><p>Ce dernier point a une conséquence visible. Une requête en flux sur le point d&#39;entrée compatible OpenAI ne porte aucun compte de tokens sauf si le client les a demandés avec <code>stream_options: { include_usage: true }</code> ; Ollama, comme OpenAI, n&#39;ajoute le fragment d&#39;usage que sur demande. LLMxRay n&#39;ajoute pas cette option à la place du client, parce que certains clients s&#39;étrangleraient sur le fragment supplémentaire. Ces tours affichent <em>non rapporté</em> dans la colonne du cache, leur anatomie d&#39;invite restant en place. L&#39;API native (<code>/api/chat</code>, <code>/api/generate</code>) rapporte toujours les comptes, et c&#39;est elle qu&#39;utilisent la ligne de commande Ollama, les SDK Ollama et le fournisseur Ollama de VS Code Copilot.</p>`,45)])])}const h=t(o,[["render",n]]);export{m as __pageData,h as default};
